BEGIN TRANSACTION;
CREATE TABLE learn_exercises (
	id              INTEGER PRIMARY KEY AUTOINCREMENT,
	topic_id        INTEGER NOT NULL REFERENCES learn_topics(id),
	word            TEXT    NOT NULL,
	sort_order      INTEGER NOT NULL DEFAULT 0,
	pass_confidence REAL    NOT NULL DEFAULT 0.8,
	published       INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE learn_progress (
	user_id         INTEGER NOT NULL,
	exercise_id     INTEGER NOT NULL REFERENCES learn_exercises(id),
	best_confidence REAL    NOT NULL DEFAULT 0,
	passed          INTEGER NOT NULL DEFAULT 0,
	updated_ms      INTEGER NOT NULL,
	PRIMARY KEY (user_id, exercise_id)
);
CREATE TABLE learn_signs (
	word            TEXT PRIMARY KEY,
	category        TEXT NOT NULL DEFAULT '',
	keypoint_frames TEXT
);
CREATE TABLE learn_topics (
	id         INTEGER PRIMARY KEY AUTOINCREMENT,
	slug       TEXT    NOT NULL UNIQUE,
	title      TEXT    NOT NULL,
	icon       TEXT    NOT NULL DEFAULT '',
	sort_order INTEGER NOT NULL DEFAULT 0,
	published  INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE predictions (
	id               INTEGER PRIMARY KEY AUTOINCREMENT,
	created_ms       INTEGER NOT NULL,
	seq              INTEGER NOT NULL,
	word             TEXT    NOT NULL,
	confidence       REAL    NOT NULL,
	is_idle          INTEGER NOT NULL,
	is_uncertain     INTEGER NOT NULL,
	inference_micros INTEGER NOT NULL,
	other_prob       REAL    NOT NULL,
	top_json         TEXT    NOT NULL
);
CREATE TABLE predlog_settings (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);
CREATE TABLE refresh_tokens (
	id         INTEGER PRIMARY KEY AUTOINCREMENT,
	user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
	token_hash TEXT    NOT NULL UNIQUE,
	expires_at INTEGER NOT NULL,
	created_at INTEGER NOT NULL
);
CREATE TABLE users (
	id            INTEGER PRIMARY KEY AUTOINCREMENT,
	email         TEXT    NOT NULL UNIQUE COLLATE NOCASE,
	password_hash TEXT    NOT NULL,
	role          TEXT    NOT NULL DEFAULT 'user',
	created_at    INTEGER NOT NULL,
	updated_at    INTEGER NOT NULL
);
CREATE INDEX idx_predictions_created ON predictions(created_ms);
CREATE INDEX idx_predictions_word ON predictions(word);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);
CREATE INDEX idx_refresh_tokens_hash ON refresh_tokens(token_hash);
CREATE INDEX idx_learn_exercises_topic ON learn_exercises(topic_id);
DELETE FROM "sqlite_sequence";
COMMIT;
